python -c "import gzip,csv,collections,datetime,math; p='data/tapas_gps_600s.csv.gz'; rows=list(csv.DictReader(gzip.open(p,'rt'))); groups=collections.defaultdict(list); invalid=0; [(groups[r['device_id']].append(r)) for r in rows]; speeds=[]; duplicates=0; gaps=0; [groups[k].sort(key=lambda x:x['timestamp']) for k in groups]; [(None) for k in []]; exec(\"for k,rs in groups.items():\\n seen=set()\\n for r in rs:\\n  t=datetime.datetime.fromisoformat(r['timestamp'])\\n  if t in seen: duplicates+=1\\n  seen.add(t)\\n for a,b in zip(rs,rs[1:]):\\n  t1=datetime.datetime.fromisoformat(a['timestamp']); t2=datetime.datetime.fromisoformat(b['timestamp']); dt=(t2-t1).total_seconds()\\n  if dt>1.01: gaps+=1\\n  if 0<dt<=1.01:\\n   dy=math.radians(float(b['latitude'])-float(a['latitude']))*6371000\\n   dx=math.radians(float(b['longitude'])-float(a['longitude']))*6371000*math.cos(math.radians(float(b['latitude'])))\\n   speeds.append(math.hypot(dx,dy)/dt)\"); print('Records:',len(rows)); print('Devices:',len(groups)); print('Invalid GPS:',sum(not(-90<=float(r['latitude'])<=90 and -180<=float(r['longitude'])<=180) for r in rows)); print('Duplicate timestamps:',duplicates); print('Gaps >1.01 sec:',gaps); print('Median speed:',round(sorted(speeds)[len(speeds)//2],2),'m/s'); print('95th percentile:',round(sorted(speeds)[int(.95*(len(speeds)-1))],2),'m/s'); print('Maximum speed:',round(max(speeds),2),'m/s')"